pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        // Skip the zero address for the call target to avoid weirdness
        vm.assume(caddress != address(0));
        // Ensure inner call will succeed (e.g., by not reverting due to missing code)
        vm.assume(caddress.code.length > 0);
        bool success = c.transfer(from, caddress, _tos, v);
        assertTrue(success);
    }
}

